solution.solution.cpp:
struct Pool
{
    int capacity{ 2 };
    int inUse{ 0 };
};

class Lease
{
public:
    explicit Lease(Pool& pool);
    ~Lease();
    bool valid() const { return m_valid; }

private:
    Pool& m_pool;
    bool m_valid{ false };
};

Lease::Lease(Pool& pool) : m_pool{ pool }
{
    if (m_pool.inUse < m_pool.capacity)
    {
        ++m_pool.inUse;
        m_valid = true;
    }
}

Lease::~Lease()
{
    if (m_valid)
    {
        --m_pool.inUse;
    }
}

unitTests:
TEST("takes and returns a connection") { Pool p{}; { Lease a{ p }; CHECK(a.valid()); CHECK_EQ(p.inUse, 1); } CHECK_EQ(p.inUse, 0); }
TEST("a full pool gives invalid leases") { Pool p{}; Lease a{ p }; Lease b{ p }; Lease c{ p }; CHECK(a.valid()); CHECK(b.valid()); CHECK(!c.valid()); CHECK_EQ(p.inUse, 2); }
TEST("an invalid lease gives nothing back") { Pool p{}; Lease a{ p }; Lease b{ p }; { Lease c{ p }; CHECK(!c.valid()); } CHECK_EQ(p.inUse, 2); }
TEST("a returned connection can be taken again") { Pool p{ 1, 0 }; { Lease a{ p }; } Lease b{ p }; CHECK(b.valid()); CHECK_EQ(p.inUse, 1); }

